package exercise

import (
	"runtime"
	"testing"
	"time"
)

func TestKnapsack(t *testing.T) {
	cases := []struct {
		name string
		W    int
		val  []int
		wt   []int
		want int
	}{
		{"two items fit alone but not together", 4, []int{1, 2, 3}, []int{4, 5, 1}, 3},
		{"nothing fits", 3, []int{1, 2, 3}, []int{4, 5, 6}, 0},
		{"best ratio first is not optimal", 50, []int{60, 100, 120}, []int{10, 20, 30}, 220},
		{"an item is counted once", 10, []int{10}, []int{3}, 10},
		{"light item would repeat", 6, []int{5, 7}, []int{1, 5}, 12},
		{"no items", 10, []int{}, []int{}, 0},
		{"zero capacity", 0, []int{5, 6}, []int{1, 2}, 0},
		{"exact fit", 5, []int{3, 4, 5}, []int{2, 3, 4}, 7},
		{"everything fits", 100, []int{1, 2, 3, 4}, []int{1, 2, 3, 4}, 10},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := Knapsack(c.W, c.val, c.wt); got != c.want {
				t.Errorf("Knapsack(%d, %v, %v) = %d, want %d", c.W, c.val, c.wt, got, c.want)
			}
		})
	}
}

func TestKnapsackTimeAndMemory(t *testing.T) {
	const n, W = 2000, 10000
	val := make([]int, n)
	wt := make([]int, n)
	for i := range val {
		val[i] = 3
		wt[i] = 7
	}
	want := (W / 7) * 3

	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	start := time.Now()
	got := Knapsack(W, val, wt)
	elapsed := time.Since(start)
	runtime.ReadMemStats(&after)

	if got != want {
		t.Fatalf("got %d, want %d", got, want)
	}
	const timeBudget = 2 * time.Second
	if elapsed > timeBudget {
		t.Fatalf("took %v with %d items and capacity %d, over the %v budget", elapsed, n, W, timeBudget)
	}
	const memBudget = 1 << 20
	if allocated := after.TotalAlloc - before.TotalAlloc; allocated > memBudget {
		t.Fatalf("allocated %d bytes with %d items and capacity %d, over the %d byte budget: memory should grow with the capacity, not with items times capacity", allocated, n, W, memBudget)
	}
}

