package exercise

func Knapsack(W int, val, wt []int) int {
	dp := make([]int, W+1)
	for i := range wt {
		for j := W; j >= wt[i]; j-- {
			dp[j] = max(dp[j], dp[j-wt[i]]+val[i])
		}
	}
	return dp[W]
}
